class Solution:
    def palindromePartition(self, s: str, t: int) -> int:
        n=len(s)
        @lru_cache(None)
        def is_palin(s):                #This function returns min no of chars to change to make s as a palindrome
            cnt=0
            for c1,c2 in zip(s,s[::-1]):
                if c1!=c2: cnt+=1
            if len(s)%2==0:
                return cnt//2
            return (cnt+1)//2
        @lru_cache(None)
        def dp(i,j,k):            #We analyse string s[i:j+1] with k divisions left
            if j==n:
                return 0 if k==0 else sys.maxsize
            if k==0: 
                return sys.maxsize
            ans=sys.maxsize
            cnt=is_palin(s[i:j+1])
            #terminate here
            ans=min(ans,dp(j+1,j+1,k-1)+cnt)
            #dont terminate
            ans=min(ans,dp(i,j+1,k))
            return ans
        return dp(0,0,t)

class Solution:
    def palindromePartition(self, s, k):
        # dp1[i][j]: minimum number of changes to make s[i, j] palindrome
        dp1 = [[0]*len(s) for _ in range(len(s))]
        for l in range(1, len(s)+1):
            for i in range(len(s)-l+1):
                j = i+l-1
                if i == j-1:
                    dp1[i][j] = 0 if s[i] == s[j] else 1
                elif i != j:
                    dp1[i][j] = dp1[i+1][j-1] if s[i] == s[j] else dp1[i+1][j-1]+1

        # dp2[d][i]: minimum number of changes to divide s[0, i] into d palindromes
        dp2 = [[float("inf")]*len(s) for _ in range(2)]
        dp2[1] = dp1[0][:]
        for d in range(2, k+1):
            dp2[d%2] = [float("inf")]*len(s)
            for i in range(d-1, len(s)):  
                for j in range(d-2, i):
                    dp2[d%2][i] = min(dp2[d%2][i], dp2[(d-1)%2][j]+dp1[j+1][i])
        return dp2[k%2][len(s)-1]

class Solution:
    def subtractProductAndSum(self, n: int) -> int:
        n_to_list = list(str(n))

        sum_of_digits = 0 
        for num in n_to_list:
            sum_of_digits = sum_of_digits + int(num)

        product_of_digits = 1
        for num in n_to_list:
            product_of_digits = product_of_digits * int(num)

        answer = product_of_digits - sum_of_digits

        return answer

